import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = 'http://localhost:8080'

def decode(resp):
    return resp.read().decode('utf-8')

def token():
    req = urllib.request.Request(BASE + '/token', method='POST')
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(decode(resp))['token']
        except urllib.error.HTTPError as e:
            if e.code == 429:
                wait = e.headers.get('Retry-After')
                try: seconds = float(wait)
                except (TypeError, ValueError): seconds = 1
                time.sleep(max(seconds, 0.1))
                continue
            if e.code >= 500:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError, ConnectionError):
            time.sleep(1)

auth = None

def get_json(path):
    global auth
    while True:
        if auth is None:
            auth = token()
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + auth})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(decode(resp))
        except urllib.error.HTTPError as e:
            if e.code == 401:
                auth = None
                continue
            if e.code == 429:
                wait = e.headers.get('Retry-After')
                body = e.read().decode('utf-8', 'replace')
                try:
                    seconds = float(wait)
                except (TypeError, ValueError):
                    try:
                        data = json.loads(body)
                        seconds = float(data.get('retry_after', data.get('wait', 1)))
                    except Exception:
                        seconds = 1
                time.sleep(max(seconds, 0.1))
                continue
            if e.code >= 500:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError, ConnectionError):
            time.sleep(1)

pages = []
page = 1
while True:
    result = get_json('/orders?page=' + str(page))
    pages.extend(result['items'])
    if result['next'] is None:
        break
    page += 1
    if page > result['total_pages'] + 1:
        raise RuntimeError('pagination exceeded total_pages')

seen = set()
unique = []
duplicates = 0
for order in pages:
    oid = order['id']
    if oid in seen:
        duplicates += 1
    else:
        seen.add(oid)
        unique.append(order)

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in unique:
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if start <= placed < end:
        qualifying.append(order)

customers = {}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = get_json('/customers/' + str(cid))

regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    customer = customers[order['customer_id']]
    numerator = order['amount_cents'] * (100 - customer['discount_pct'])
    sign = -1 if numerator < 0 else 1
    absolute = abs(numerator)
    discounted = sign * (absolute // 100 + (1 if absolute % 100 >= 50 else 0))
    regions[customer['region']] += discounted

output = {
    'total_cents': sum(regions.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': regions,
}
with open('/workspace/result.json', 'w') as f:
    json.dump(output, f, indent=2)
    f.write('\\n')
print(json.dumps({'page_count': page, 'listed_count': len(pages), 'unique_count': len(unique), 'qualifying_count': len(qualifying), 'customer_count': len(customers), 'result': output}, indent=2))
